using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayerScoreXPData", menuName = "Data/ScoreXP/PlayerScoreXPData")]
public class PlayerScoreXPData : ScriptableObject
{
	[Header("Score XP Item Datas")]
	[SerializeField]
	private BattleScoreXPItemDatasNodeEnum[] battleScoreXPItemDatasNodeEnums;

	[SerializeField]
	private ScoreXPItemData starShardsScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData heartsSacrificedShrineScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData heartsLostBattleScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData astreaFirstPhaseBattleScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData astreaSecondPhaseBattleScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData anomalyLevelScoreXPItemData;

	[SerializeField]
	private ScoreXPItemData astreaLevelScoreXPItemData;

	[Header("Assets")]
	[SerializeField]
	private MapHandler mapHandler;

	public List<ScoreXPItemDataRuntime> ScoreXPItemDatasRuntime;

	public int HeartsSacrificedCounter;

	[NonSerialized]
	[ShowNonSerializedField]
	public int HeartsLostOnBattleCounter;

	public int GetRunScoreXP()
	{
		IncreaseScoreXPItemData(starShardsScoreXPItemData, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentGold);
		IncreaseScoreXPItemData(heartsSacrificedShrineScoreXPItemData, HeartsSacrificedCounter);
		IncreaseScoreXPItemData(heartsLostBattleScoreXPItemData, HeartsLostOnBattleCounter);
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel > 0)
		{
			IncreaseScoreXPItemData(anomalyLevelScoreXPItemData, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel);
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel > 0)
		{
			IncreaseScoreXPItemData(astreaLevelScoreXPItemData, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreaLevel);
		}
		int num = 0;
		for (int i = 0; i < ScoreXPItemDatasRuntime.Count; i++)
		{
			num += ScoreXPItemDatasRuntime[i].scoreXPItemAmount * ScoreXPItemDatasRuntime[i].scoreXPItemData.GetScoreXPItemValue();
		}
		RearrangeListBasedOnPriorityList();
		return num;
	}

	[Button(null)]
	private void RearrangeListBasedOnPriorityList()
	{
		ScoreXPItemDatasRuntime.Sort((ScoreXPItemDataRuntime x, ScoreXPItemDataRuntime y) => x.scoreXPItemData.PriorityOnScoreXPList.CompareTo(y.scoreXPItemData.PriorityOnScoreXPList));
	}

	[Button(null)]
	public void OnResetToStartRunState()
	{
		ScoreXPItemDatasRuntime.Clear();
		HeartsSacrificedCounter = 0;
		HeartsLostOnBattleCounter = 0;
	}

	public void NonAstreaBattleWonAddScoreXPItemData()
	{
		NodeEnum nodeEnum = mapHandler.CurrentNodeData.NodeEnum;
		int currentAreaIndex = mapHandler.CurrentAreaIndex;
		if (nodeEnum == NodeEnum.EVENT)
		{
			nodeEnum = (mapHandler.CurrentCustomEventSetup as AmbushCustomEventSetup).NodeEnum;
		}
		for (int i = 0; i < battleScoreXPItemDatasNodeEnums.Length; i++)
		{
			BattleScoreXPItemDatasNodeEnum battleScoreXPItemDatasNodeEnum = battleScoreXPItemDatasNodeEnums[i];
			if (nodeEnum != battleScoreXPItemDatasNodeEnum.nodeEnum)
			{
				continue;
			}
			for (int j = 0; j < battleScoreXPItemDatasNodeEnum.battleScoreXPItemDatas.Length; j++)
			{
				BattleScoreXPItemDatas battleScoreXPItemDatas = battleScoreXPItemDatasNodeEnum.battleScoreXPItemDatas[j];
				if (currentAreaIndex == battleScoreXPItemDatas.areaIndex)
				{
					IncreaseScoreXPItemData(battleScoreXPItemDatas.scoreXPItemData, 1);
				}
			}
		}
	}

	public void AstreaFirstPhaseBattleWon()
	{
		IncreaseScoreXPItemData(astreaFirstPhaseBattleScoreXPItemData, 1);
	}

	public void AstreaSecondPhaseBattleWon()
	{
		IncreaseScoreXPItemData(astreaSecondPhaseBattleScoreXPItemData, 1);
	}

	private void IncreaseScoreXPItemData(ScoreXPItemData scoreXPItemData, int amount)
	{
		if (amount == 0)
		{
			return;
		}
		for (int i = 0; i < ScoreXPItemDatasRuntime.Count; i++)
		{
			if (ScoreXPItemDatasRuntime[i].scoreXPItemData == scoreXPItemData)
			{
				ScoreXPItemDatasRuntime[i].scoreXPItemAmount += amount;
				return;
			}
		}
		ScoreXPItemDatasRuntime.Add(new ScoreXPItemDataRuntime(scoreXPItemData, amount));
	}
}
